private boolean summonEntity(StoredEntity storedEntity, UseOnContext context) {
        BlockPos pos = context.getClickedPos();
        Level level = context.getLevel();
        Entity entity = storedEntity.createEntity(level);

        if (!level.getBlockState(pos).canBeReplaced(new BlockPlaceContext(context))) {
            pos = pos.relative(context.getClickedFace());
        }

        if (entity == null || !level.getBlockState(pos).canBeReplaced(new BlockPlaceContext(context))) {
            return false;
        }

        entity.setPos(pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D);

        if (context.getPlayer() != null) {
            entity.lookAt(EntityAnchorArgument.Anchor.EYES, context.getPlayer().position());
        }
        level.addFreshEntity(entity);

        context.getItemInHand().remove(ModDataComponents.STORED_ENTITY);

        return true;
    }

@Override
    public InteractionResult useOn(UseOnContext context) {
        ItemStack stack = context.getItemInHand();

        Optional<StoredEntity> storedEntity = getData(stack);

        if (storedEntity.isEmpty()) {
            return super.useOn(context);
        }

        return storedEntity.map(entity -> {
            Level level = context.getLevel();

            if (!level.isClientSide()) {
                if (!this.summonEntity(storedEntity.get(), context)) {
                    return InteractionResult.FAIL;
                }
            }

            playSound(level, context.getPlayer(), context.getClickedPos(), false);

            return InteractionResult.SUCCESS;
        }).orElseThrow();
    }

public InteractionResult onEntityInteract(ItemStack stack, Player player, LivingEntity target) {
        Level level = player.level();
        EssenceCost cost = calculateAurealCost(target);

        if (!this.isValidEntity(target) || getData(stack).isPresent()) {
            return InteractionResult.PASS;
        }

        if (!cost.hasEnough(player)) {
            return InteractionResult.FAIL;
        }

        if (!level.isClientSide()) {
            if (stack.getCount() == 1) {
                stack.set(ModDataComponents.STORED_ENTITY, StoredEntity.of(target));
            } else {
                stack.consume(1, player);

                stack = new ItemStack(ModItems.QUANTUM_CATCHER.get());
                stack.set(ModDataComponents.STORED_ENTITY, StoredEntity.of(target));

                if (!player.addItem(stack)) {
                    player.drop(stack, false);
                }
            }

            target.discard();

            cost.consume(player);
        }

        playSound(level, player, target.blockPosition(), true);

        return InteractionResult.SUCCESS;
    }

public boolean isValidEntity(LivingEntity entity) {
        return !entity.is(this.blacklistedEntities) && entity.isAlive();
    }

public static EssenceCost calculateAurealCost(LivingEntity entity) {
        int health = Math.round(entity.getMaxHealth());

        if (entity.getType().getCategory().isFriendly()) {
            health = health >> 1;
        } else {
            health = (int) (health * 1.1F);
        }

        return EssenceCost.of(EssenceType.AUREAL, health, EssenceCosts.CATCH_COMPONENT);
    }

private static Optional<StoredEntity> getData(ItemStack stack) {
        return Optional.ofNullable(stack.get(ModDataComponents.STORED_ENTITY));
    }

private static void playSound(Level level, @Nullable Player player, BlockPos pos, boolean release) {
        BlockPos soundPos = player == null ? pos : player.blockPosition();

        level.playSound(player, soundPos.getX() + 0.5D, soundPos.getY() + 0.5D, soundPos.getZ() + 0.5D, release ? ModSounds.QUANTUM_CATCHER_RELEASE.get() : ModSounds.QUANTUM_CATCHER_PICK_UP.get(), SoundSource.PLAYERS, 0.75F, level.getRandom().nextFloat() * 0.15F + 0.9F);
    }

public static StoredEntity of(LivingEntity entity) {
        entity.stopRiding();
        entity.ejectPassengers();

        TypedEntityData<EntityType<?>> data;

        try (ProblemReporter.ScopedCollector scopedCollector = new ProblemReporter.ScopedCollector(entity.problemPath(), LOGGER)) {
            TagValueOutput output = TagValueOutput.createWithContext(scopedCollector, entity.registryAccess());

            entity.save(output);

            IGNORED_TAGS.forEach(output::discard);

            data = TypedEntityData.of(entity.getType(), output.buildResult());
        }

        return new StoredEntity(data);
    }

@Nullable
    public Entity createEntity(Level level) {
        return EntityType.loadEntityRecursive(this.data.type(), this.data.copyTagWithoutId(), level, EntitySpawnReason.SPAWN_ITEM_USE, EntityProcessor.NOP);
    }

@SubscribeEvent
    public void onEntityInteract(PlayerInteractEvent.EntityInteract event) {
        Player player = event.getEntity();
        ItemStack stack = event.getItemStack();

        if (event.getTarget() instanceof LivingEntity entity && stack.getItem() instanceof QuantumCatcherItem item) {
            event.setCancellationResult(item.onEntityInteract(stack, player, entity));
            event.setCanceled(true);
        }
    }

public boolean hasEnough(LivingEntity livingEntity) {
        return EssenceHelper.getEssenceAccess(livingEntity)
                .map(access -> access.getEssenceAmount(this.value.type()) >= this.value.amount())
                .orElse(false);
    }

public void consume(LivingEntity livingEntity) {
        EssenceHelper.addEssence(livingEntity, this.value.type(), -this.value.amount());
    }

public static Optional<EssenceAccess> getEssenceAccess(Entity entity) {
        return Optional.ofNullable(entity.getCapability(EssenceAccess.ENTITY_CAPABILITY));
    }

public static void addEssence(Entity entity, EssenceType essenceType, int amount) {
        getEssenceAccess(entity).ifPresent(essenceAccess -> {
            essenceAccess.addEssence(essenceType, amount);
        });
    }

public void finishRitual(ServerLevel level, BlockPos pos, ActiveRitualData data, HephaestusForgeSharedData sharedData) {
        ServerPlayer initiator = EntityReference.get(this.ritualInitiator, level, ServerPlayer.class);

        this.resetRitual(level, sharedData);

        ItemStack result = data.finish(level, pos, initiator, sharedData.getMainSlotInventory().getStack());
        sharedData.getMainSlotInventory().setStack(result);

        level.sendParticles(ModParticles.MAGIC_EXPLOSION.get(), pos.getX() + 0.5D, pos.getY() + 1.4D, pos.getZ() + 0.5D, 1, 0.0D, 0.0D, 0.0D, 0.0D);
    }

@Override
    protected InteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand, BlockHitResult result) {
        this.updateState(state, level, pos);

        RitualStarter ritualStarter = stack.get(ModDataComponents.RITUAL_STARTER);

        if (state.getValue(ACTIVATED) && ritualStarter != null && level.getBlockEntity(pos) instanceof HephaestusForgeBlockEntity blockEntity) {
            level.playSound(player, pos, ritualStarter.soundEvent().value(), SoundSource.PLAYERS, 0.85F, level.getRandom().nextFloat() * 0.15F + 0.9F);

            if (level instanceof ServerLevel serverLevel && player instanceof ServerPlayer serverPlayer && blockEntity.startRitual(serverLevel, serverPlayer)) {
                stack.hurtAndBreak(ritualStarter.damagePerRitual(), player, hand.asEquipmentSlot());
            }

            return InteractionResult.SUCCESS;
        }

        return super.useItemOn(stack, state, level, pos, player, hand, result);
    }

@Nullable
    @Override
    public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level, BlockState state, BlockEntityType<T> blockEntityType) {
        if (level.isClientSide()) {
            return BaseEntityBlock.createTickerHelper(blockEntityType, ModBlockEntities.HEPHAESTUS_FORGE.get(), HephaestusForgeBlockEntity::clientTick);
        }
        return BaseEntityBlock.createTickerHelper(blockEntityType, ModBlockEntities.HEPHAESTUS_FORGE.get(), HephaestusForgeBlockEntity::serverTick);
    }

public static void serverTick(Level level, BlockPos pos, BlockState state, HephaestusForgeBlockEntity blockEntity) {
        blockEntity.serverData.tick(blockEntity.sharedData);

        if (level instanceof ServerLevel serverLevel) {
            for (TickEffect effect : blockEntity.tickEffects) {
                if (serverLevel.getGameTime() % effect.getTickInterval() == 0) {
                    effect.tick(serverLevel, pos, state);
                }
            }

            if (blockEntity.sharedData.isDirty || blockEntity.serverData.isDirty) {
                blockEntity.serverData.onDataChanged(serverLevel, pos, blockEntity.sharedData);
                blockEntity.setChanged();

                blockEntity.serverData.isDirty = false;
            }

            if (blockEntity.sharedData.isDirty) {
                serverLevel.sendBlockUpdated(pos, state, state, 2);

                blockEntity.sharedData.isDirty = false;
            }
        }
    }

public boolean startRitual(ServerLevel level, ServerPlayer player) {
        return this.serverData.startRitual(level, this.getBlockPos(), player, this.sharedData);
    }

@Override
    protected void saveAdditional(ValueOutput output) {
        super.saveAdditional(output);

        this.serverData.save(output);
        output.store(HephaestusForgeSharedData.CODEC, this.sharedData);
    }

@Override
    protected void loadAdditional(ValueInput input) {
        super.loadAdditional(input);

        this.serverData.load(input);
        input.read(HephaestusForgeSharedData.CODEC).ifPresent(this.sharedData::set);
    }

public boolean startRitual(ServerLevel level, BlockPos pos, ServerPlayer player, HephaestusForgeSharedData sharedData) {
        if (sharedData.getActiveRitualData().isPresent()) {
            return false;
        }

        return sharedData.getValidRitual().map(ritual -> {
            this.setActiveRitual(ritual, player, sharedData);

            sharedData.removeEssences(ritual.value().requirements().essences());
            sharedData.setValidRitual(null);

            this.forEachPedestal(level, PedestalBlockEntity::hasStack, blockEntity -> {
                blockEntity.setItemHeightTarget(PEDESTAL_ITEM_HEIGHT);
            });

            return true;
        }).orElse(false);
    }

private void setActiveRitual(@Nullable Holder<Ritual> ritual, @Nullable ServerPlayer initiator, HephaestusForgeSharedData sharedData) {
        this.ritualInitiator = initiator != null ? EntityReference.of(initiator) : null;
        sharedData.setActiveRitualData(ritual != null ? ActiveRitualData.create(ritual) : null);
    }

private void resetRitual(ServerLevel level, HephaestusForgeSharedData sharedData) {
        sharedData.setValidRitual(null);
        this.setActiveRitual(null, null, sharedData);
        this.clearPedestals(level);
    }

private void clearPedestals(ServerLevel level) {
        this.forEachPedestal(level, PedestalBlockEntity::hasStack, blockEntity -> {
            blockEntity.clearStack(null, PedestalEffectTrigger.RITUAL_FINISHED);

            BlockPos pedestalPos = blockEntity.getBlockPos();
            level.sendParticles(ParticleTypes.POOF, pedestalPos.getX() + 0.5D, pedestalPos.getY() + 1.4D, pedestalPos.getZ() + 0.5D, 6, 0.12D, 0.12D, 0.12D, 0.02D);
        });

        this.pedestalItems.clear();
    }

private void forEachPedestal(ServerLevel level, Predicate<PedestalBlockEntity> predicate, Consumer<PedestalBlockEntity> consumer) {
        for (BlockPos pedestalPos : this.pedestalItems.keySet()) {
            if (level.getBlockEntity(pedestalPos) instanceof PedestalBlockEntity blockEntity && predicate.test(blockEntity)) {
                consumer.accept(blockEntity);
            }
        }
    }

private void failRitual(ServerLevel level, BlockPos pos, HephaestusForgeSharedData sharedData) {
        ItemStack stack = sharedData.getMainSlotInventory().getStack();

        this.resetRitual(level, sharedData);

        if (!stack.isEmpty()) {
            level.addFreshEntity(new ItemEntity(level, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, stack));
        }

        level.sendParticles(ModParticles.HUGE_MAGIC_EXPLOSION.get(), pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D, 0, 1.0D, 0.0D, 0.0D, 0.0D);
        level.playSound(null, pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D, SoundEvents.GENERIC_EXPLODE.value(), SoundSource.BLOCKS, 4.0F, (1.0F + (level.getRandom().nextFloat() - level.getRandom().nextFloat()) * 0.2F) * 0.7F);

        sharedData.getMainSlotInventory().setStack(ItemStack.EMPTY);
    }

public void onDataChanged(ServerLevel level, BlockPos pos, HephaestusForgeSharedData sharedData) {
        sharedData.getActiveRitualData().ifPresentOrElse(activeRitualData -> {
            if (!activeRitualData.isStillValid(sharedData.getMainSlotInventory().getStack(), this.pedestalItems.values())) {
                this.failRitual(level, pos, sharedData);
            } else {
                this.forEachPedestal(level, PedestalBlockEntity::hasStack, blockEntity -> {
                    blockEntity.setItemHeightTarget(PEDESTAL_ITEM_HEIGHT);
                });
            }
        }, () -> this.updateValidRitual(level, this.createState(sharedData), sharedData));
    }

public void updatePedestalStack(BlockPos pos, ItemStack stack) {
        if (stack.isEmpty()) {
            if (this.pedestalItems.remove(pos) != null) {
                this.isDirty = true;
            }
        } else {
            this.pedestalItems.put(pos, stack);
            this.isDirty = true;
        }
    }

public void save(ValueOutput output) {
        this.enhancerInventory.serialize(output.child("enhancers"));
        this.essenceInputInventory.serialize(output.child("inputs"));
        output.store(CODEC, this);
    }

public void load(ValueInput input) {
        this.enhancerInventory.deserialize(input.childOrEmpty("enhancers"));
        this.essenceInputInventory.deserialize(input.childOrEmpty("inputs"));
        input.read(CODEC).ifPresent(this::set);
    }

public void setActiveRitualData(@Nullable ActiveRitualData activeRitualData) {
        if (!Objects.equals(this.activeRitualData, activeRitualData)) {
            this.activeRitualData = activeRitualData;
            this.isDirty = true;
        }
    }

public void setValidRitual(@Nullable Holder<Ritual> validRitual) {
        if (!Objects.equals(this.validRitual, validRitual)) {
            this.validRitual = validRitual;
            this.isDirty = true;
        }
    }

void set(HephaestusForgeSharedData from) {
        this.tier = from.tier;
        this.essenceStorage = from.essenceStorage;
        this.mainSlotInventory.setStack(from.mainSlotInventory.getStack());
        this.validRitual = from.validRitual;
        if (this.activeRitualData == null || from.activeRitualData == null || !Objects.equals(this.activeRitualData.getRitual(), from.activeRitualData.getRitual())) {
            this.activeRitualData = from.activeRitualData;
        }
        this.isDirty = false;
    }

@Override
    public void tick(ServerLevel level, BlockPos pos, BlockState state) {
        this.sharedData.getActiveRitualData().ifPresent(activeRitualData -> {
            activeRitualData.incrementTicks();

            float progress = activeRitualData.calculateRitualProgress();

            this.serverData.getPedestalItems().forEach((pedestalPos, stack) -> {
                this.addItemParticles(level, pos, pedestalPos, Math.min(PedestalBlockEntity.DEFAULT_ITEM_HEIGHT + activeRitualData.getTicks(), HephaestusForgeServerData.PEDESTAL_ITEM_HEIGHT), ItemStackTemplate.fromNonEmptyStack(stack));
            });

            if (progress == 1.0F) {
                this.serverData.finishRitual(level, pos, activeRitualData, this.sharedData);
            }
        });
    }

@Override
    public int getTickInterval() {
        return 1;
    }

public static ActiveRitualData create(Holder<Ritual> ritual) {
        return new ActiveRitualData(ritual, 0);
    }

public void incrementTicks() {
        this.ticks++;
    }

public float calculateRitualProgress() {
        return this.ticks / (float) this.ritual.value().duration();
    }

public ItemStack finish(ServerLevel level, BlockPos pos, @Nullable ServerPlayer startedBy, ItemStack mainIngredient) {
        if (startedBy != null && this.getRitualId() != null) {
            FACriteriaTriggers.RITUAL.get().trigger(startedBy, this.getRitualId());
        }

        RitualResult result = this.getRitual().result();

        result.executeLevelEffect(level, pos);

        return result.getResultItem(mainIngredient);
    }

public boolean isStillValid(ItemStack mainItem, Collection<ItemStack> pedestalItems) {
        return this.getRitual().checkIngredients(pedestalItems, mainItem);
    }

public void clearStack(@Nullable Player player, PedestalEffectTrigger trigger) {
        this.itemHeight = DEFAULT_ITEM_HEIGHT;

        this.setStack(ItemStack.EMPTY, player, trigger);
    }

public void setStack(ItemStack stack, @Nullable Player player, PedestalEffectTrigger trigger) {
        this.stack = stack;

        this.markUpdated();

        if (this.level instanceof ServerLevel serverLevel) {
            serverLevel.gameEvent(GameEvent.BLOCK_CHANGE, this.getBlockPos(), GameEvent.Context.of(player, this.getBlockState()));

            FARegistries.PEDESTAL_EFFECT_REGISTRY.stream().filter(pedestalEffect -> pedestalEffect.shouldExecute(trigger)).forEach(pedestalEffect -> {
                pedestalEffect.execute(serverLevel, this.getBlockPos(), stack);
            });

            this.level.playSound(null, this.getBlockPos(), ModSounds.PEDESTAL_INTERACT.get(), SoundSource.BLOCKS, 0.8F, level.getRandom().nextFloat() * 0.15F + 0.9F - (stack.isEmpty() ? 0.3F : 0.0F));
        }
    }
